'use strict';
const assert = require('node:assert/strict');
const { diffLines, unifiedHunks, applyHunks } = require('./src/diff');

function lcs(a, b) {
  const dp = Array.from({ length: a.length + 1 }, () => new Array(b.length + 1).fill(0));
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] = a[i] === b[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1]);
  return dp[0][0];
}
let seed = 12345;
const rnd = (n) => ((seed = (seed * 1103515245 + 12345) >>> 0) % n);
const alpha = ['x', 'y', '', '-x', '+y', ' z', 'w'];
for (let t = 0; t < 20000; t++) {
  const a = Array.from({ length: rnd(12) }, () => alpha[rnd(alpha.length)]);
  const b = rnd(3) === 0
    ? Array.from({ length: rnd(12) }, () => alpha[rnd(alpha.length)])
    : a.filter(() => rnd(4) !== 0).flatMap((l) => (rnd(5) === 0 ? [l, alpha[rnd(7)]] : [l]));
  const sa = a.slice(), sb = b.slice();
  const s = diffLines(a, b);
  assert.deepEqual(s.filter((e) => e.op !== 'insert').map((e) => e.line), a);
  assert.deepEqual(s.filter((e) => e.op !== 'delete').map((e) => e.line), b);
  assert.equal(s.filter((e) => e.op !== 'equal').length, a.length + b.length - 2 * lcs(a, b));
  for (let i = 1; i < s.length; i++) assert.ok(!(s[i - 1].op === 'insert' && s[i].op === 'delete'));
  assert.deepEqual(diffLines(a, b), s);
  for (const context of [0, 1, 2, 3]) {
    const h = unifiedHunks(a, b, { context });
    if (s.every((e) => e.op === 'equal')) assert.deepEqual(h, []);
    assert.deepEqual(applyHunks(a, h), b);
    // each hunk applied alone must also apply to a
    for (const hk of h) applyHunks(a, [{ ...hk, newStart: hk.newStart - h[0].newStart + h[0].oldStart }].slice(0, 0));
  }
